for label,command in commands:
 p=subprocess.run(command,text=True,capture_output=True,timeout=8);r['commands'][label]={'returncode':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
r['finished_utc']=datetime.now(timezone.utc).isoformat();print(json.dumps(r))
